import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { ref, onValue, update } from 'firebase/database';
import { db } from '../firebase';

function SeriesDetail() {
  const { id } = useParams();
  const [series, setSeries] = useState(null);
  const [loading, setLoading] = useState(true);
  const [watchedEpisodes, setWatchedEpisodes] = useState([]);

  useEffect(() => {
    const seriesRef = ref(db, `series/${id}`);
    const unsubscribe = onValue(seriesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setSeries({ id, ...data });
        setWatchedEpisodes(data.watchedEpisodes || []);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [id]);

  const toggleEpisodeWatched = async (season, episode) => {
    const episodeKey = `${season}-${episode}`;
    const newWatchedEpisodes = watchedEpisodes.includes(episodeKey)
      ? watchedEpisodes.filter(ep => ep !== episodeKey)
      : [...watchedEpisodes, episodeKey];

    try {
      const seriesRef = ref(db, `series/${id}`);
      await update(seriesRef, {
        watchedEpisodes: newWatchedEpisodes
      });
      setWatchedEpisodes(newWatchedEpisodes);
    } catch (error) {
      console.error('Error updating episode status: ', error);
    }
  };

  if (loading) {
    return (
      <div className="text-center">
        <p className="text-xl">Yükleniyor...</p>
      </div>
    );
  }

  if (!series) {
    return (
      <div className="text-center">
        <p className="text-xl">Dizi bulunamadı.</p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-md p-8">
      <h2 className="text-3xl font-bold text-purple-600 mb-6">{series.title}</h2>
      
      <div className="mb-8">
        <div className="grid grid-cols-2 gap-4 text-gray-600">
          <div>
            <p className="font-semibold">Toplam Sezon:</p>
            <p>{series.totalSeasons}</p>
          </div>
          <div>
            <p className="font-semibold">Sezon Başına Bölüm:</p>
            <p>{series.episodesPerSeason}</p>
          </div>
          <div>
            <p className="font-semibold">Mevcut Sezon:</p>
            <p>{series.currentSeason}</p>
          </div>
          <div>
            <p className="font-semibold">Mevcut Bölüm:</p>
            <p>{series.currentEpisode}</p>
          </div>
          <div>
            <p className="font-semibold">İzleme Durumu:</p>
            <p>{series.watchingTogether ? 'Birlikte İzliyoruz' : 'Ayrı İzliyoruz'}</p>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <h3 className="text-xl font-bold text-purple-600">Bölümler</h3>
        {Array.from({ length: series.currentSeason }, (_, seasonIndex) => (
          <div key={seasonIndex + 1} className="border rounded-lg p-4">
            <h4 className="text-lg font-semibold mb-3">Sezon {seasonIndex + 1}</h4>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-2">
              {Array.from(
                { length: seasonIndex + 1 === series.currentSeason ? series.currentEpisode : series.episodesPerSeason },
                (_, episodeIndex) => {
                  const episodeKey = `${seasonIndex + 1}-${episodeIndex + 1}`;
                  const isWatched = watchedEpisodes.includes(episodeKey);
                  
                  return (
                    <button
                      key={episodeIndex + 1}
                      onClick={() => toggleEpisodeWatched(seasonIndex + 1, episodeIndex + 1)}
                      className={`p-2 rounded-lg text-center ${
                        isWatched
                          ? 'bg-green-500 text-white'
                          : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                      }`}
                    >
                      Bölüm {episodeIndex + 1}
                    </button>
                  );
                }
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default SeriesDetail;
